CREATE COLUMN TABLE "TEST_AP"."QUE2" ("queueID" NVARCHAR(20) NOT NULL , "objType" NVARCHAR(20) NOT NULL , "elementId" INTEGER CS_INT NOT NULL , "elementNum" INTEGER CS_INT NOT NULL , "priority" INTEGER CS_INT, "createDate" LONGDATE CS_LONGDATE, "createTime" SMALLINT CS_INT, PRIMARY KEY ("queueID", "elementNum")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE UNIQUE INDEX "QUE2_OBJ_ELEM" ON "TEST_AP"."QUE2" ( "queueID" ASC, "objType" ASC, "elementId" ASC )